merge into T_TM_MONTH_PLAN_SURPLUS a USING (
select #{ITEM.monthPlanApsVersion,jdbcType=VARCHAR} MONTH_PLAN_APS_VERSION, #{ITEM.monthPlanVersion,jdbcType=VARCHAR} MONTH_PLAN_VERSION, #{ITEM.year,jdbcType=VARCHAR} YEAR, #{ITEM.month,jdbcType=VARCHAR} MONTH, #{ITEM.materialCode,jdbcType=VARCHAR} MATERIAL_CODE, #{ITEM.monthPlanQty,jdbcType=DECIMAL} MONTH_PLAN_QTY, #{ITEM.monthPlanModifyQty,jdbcType=DECIMAL} MONTH_PLAN_MODIFY_QTY, #{ITEM.monthFinishQty,jdbcType=DECIMAL} MONTH_FINISH_QTY, #{ITEM.monthRemainQty,jdbcType=DECIMAL} MONTH_REMAIN_QTY, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.year = b.year AND a.month = b.month AND a.MATERIAL_CODE = b.MATERIAL_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.MONTH_PLAN_QTY = NVL(b.MONTH_PLAN_QTY, 0), a.MONTH_PLAN_MODIFY_QTY = NVL(b.MONTH_PLAN_MODIFY_QTY, 0), a.MONTH_FINISH_QTY = NVL(b.MONTH_FINISH_QTY, 0), a.MONTH_REMAIN_QTY = NVL(b.MONTH_REMAIN_QTY, 0), a.update_by = b.create_by, a.update_time = now() WHEN NOT MATCHED THEN INSERT (a.id, a.MONTH_PLAN_APS_VERSION, a.MONTH_PLAN_VERSION, a.YEAR, a.MONTH, a.MATERIAL_CODE, a.MONTH_PLAN_QTY, a.MONTH_PLAN_MODIFY_QTY, a.MONTH_FINISH_QTY, a.MONTH_REMAIN_QTY, a.create_by, a.create_time, a.remark, a.del_flag) values (T_TM_MONTH_PLAN_SURPLUS_SEQ.NEXTVAL, b.MONTH_PLAN_APS_VERSION, b.MONTH_PLAN_VERSION, b.YEAR, b.MONTH, b.MATERIAL_CODE, NVL(b.MONTH_PLAN_QTY, 0), NVL(b.MONTH_PLAN_MODIFY_QTY, 0), NVL(b.MONTH_FINISH_QTY, 0), NVL(b.MONTH_REMAIN_QTY, 0), b.create_by, now(), b.remark, '0')

