mapper.select:
    	SELECT DISTINCT MONTH_PLAN_APS_VERSION
		  FROM T_MDM_MONTH_PLAN_MAIN
		 WHERE YEAR = #{year}
		   AND MONTH = #{month}
		   AND IS_FINALIZED = '0'
		   AND DEL_FLAG = '0'
